import styles from './errorBoundary.module.less';
import { Button } from '@douyinfe/semi-ui';
import React, { Component } from 'react';

interface ErrorBoundaryProps {
  children?: JSX.Element;
}

interface ErrorBoundaryStates {
  errorMsgMap: any;
  hasError: boolean;
  errorMsg: string;
}

export interface IAppProps {}

export default class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryStates> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = {
      hasError: false,
      errorMsg: '',
      errorMsgMap: {
        timeout: '죄송합니다, 로딩 시간이 초과되었습니다!', // 오류 메시지에 대한 안내 텍스트
      },
    };
  }

  static getDerivedStateFromError(error: any) {
    // state를 업데이트하여 다음 렌더링에서 폴백 UI를 표시할 수 있도록 합니다
    return { hasError: true, errorMsg: error.message };
  }

  // componentDidCatch (error, errorInfo) {
  //     // 오류 로그를 서버에 전송할 수 있습니다
  //     logErrorToMyService(error, errorInfo);
  // }

  public render() {
    const { errorMsgMap, hasError, errorMsg } = this.state;

    if (hasError !== false) {
      // 사용자 정의 UI를 렌더링할 수 있습니다
      return (
        <div className={styles.errorBoundary}>
          <h1>{errorMsgMap[errorMsg] || '죄송합니다, 로드에 실패했습니다!'}</h1>
          <Button type="primary" key="console" onClick={() => window.location.reload()}>
            다시 로드
          </Button>
        </div>
      );
    } else {
      return this.props.children;
    }
  }
}

import React from 'react';
import { Spin, Empty } from '@douyinfe/semi-ui';
/**
 * data === null은 로딩 상태를 나타냅니다
 * @param {props}
 * @returns
 */
interface ListStatusProps {
  data: any;
  loading?: JSX.Element;
  empty?: JSX.Element;
  error?: JSX.Element;
  children: JSX.Element;
}

export default function ListStatus({ data, loading, empty, error, children }: ListStatusProps): JSX.Element {
  if (!loading) {
    loading = (
      <Spin size="large" tip="로딩 중...">
        {children}
      </Spin>
    );
  }

  if (data === null) {
    return loading;
  }

  if (data.length === 0) {
    return empty || <Empty description="데이터가 없습니다" />;
  }

  if (error) {
    return error;
  }

  return children;
}

