          crossOrigin="anonymous"
          style={{ width: 160 }}
          src={url.replace('https://mp.weixin.qq.com', '') || 'https://cdn.h5ds.com/static/images/qrcode-loading.png'}
          alt=""
        />
      </div>
    );
  }
}

