// Mock数据
import { editor } from '@stores/editor';
import { pubsub } from '@utils/pubsub';
import { userService } from '@server/user.service';
import { Toast } from '@douyinfe/semi-ui';
import { server } from './server';
import { tdata } from './tdata2';
import DragItem from './common/dragitem';
import HotKeys from './HotKeys';
import { config } from '@config/index';
import { utils } from '@pages/editor/core';

interface IProps {
  match: { params: { appid: string } };
}

const OPTION_WIDTH = 300;
function Editor(props: IProps) {
  const appid = props.match.params.appid;

  const { width = window.innerWidth, height = window.innerHeight, ref } = useResizeDetector();
  const HEADER_HEIGHT = 60;
  const SIDEBAR_WIDTH = 60;
  const [layout, setLayout] = useState({
    sourcesWidth: 310,
    optionsWidth: OPTION_WIDTH,
    timelineHeight: 300,
  });
  const [show, setShow] = useState({ sources: true, options: true });
  const [loading, setLoading] = useState(true);

  // 拖动过程中center不要动画
  const [noAnimate, setNoAnimate] = useState(false);

  // sourcesBar 移动
  const sourcesBarDrag = useCallback((e: any) => {
    setNoAnimate(true);
    const { sourcesWidth, optionsWidth } = layout;
    // canvas最小600px
    const interval = [310, window.innerWidth - optionsWidth - 600];
    $(document)
      .on('mousemove.ievent.sourcesBar', (em: any) => {
        const ex = em.pageX - e.pageX;
        let sw = sourcesWidth + ex;
        if (sw < interval[0]) {
          sw = interval[0];
        } else if (sw > interval[1]) {
          sw = interval[1];
        }
        layout.sourcesWidth = sw;
        setLayout({ ...layout });
      })
      .on('mouseup.ievent.sourcesBar', () => {
        $(document).off('mousemove.ievent.sourcesBar');
        $(document).off('mousedown.ievent.sourcesBar');
        setNoAnimate(false);
      });
  }, []);

  // 设置区域拖动
  const optionsBarDrag = useCallback((e: any) => {
    setNoAnimate(true);
    const { sourcesWidth, optionsWidth } = layout;
    const interval = [OPTION_WIDTH, window.innerWidth - sourcesWidth - 600];
    $(document)
      .on('mousemove.ievent.optionsBar', (em: any) => {
        const ex = em.pageX - e.pageX;
        let sw = optionsWidth - ex;
        if (sw < interval[0]) {
          sw = interval[0];
        } else if (sw > interval[1]) {
          sw = interval[1];
        }
        layout.optionsWidth = sw;
        setLayout({ ...layout });
      })
      .on('mouseup.ievent.optionsBar', () => {
        $(document).off('mousemove.ievent.optionsBar');
        $(document).off('mousedown.ievent.optionsBar');
        setNoAnimate(false);
      });
  }, []);

  const showPanel = (type: 'options' | 'sources', v: boolean) => {
    setShow({ ...show, [type]: v });
  };

  useEffect(() => {
    pubsub.subscribe('showLayoutPanel', (_msg, params: { type: 'options' | 'sources'; visible: boolean }) => {
      setShow({ ...show, [params.type]: params.visible });
    });
    return () => {
      pubsub.unsubscribe('showLayoutPanel');
    };
  }, [show]);

  const initAppData = useCallback(async () => {
    if (appid) {
      editor.appid = appid;
      const [res, err] = await server.getAppDetail(appid);
      if (err) {
        // 去掉APPID
        // window.history.pushState(null, null, '/editor');
        location.href = '/editor';
        Toast.error(err);
      } else {
        // console.log('resresres', res);
        const json = (await $.get(utils.setURL(res.draft_url, config.resourcesHost) + '?t=' + +new Date())) as any;
        editor.data = json;
      }
    }
    if (!editor.data) {
      editor.data = tdata;
    }
    editor.selectPageId = editor.data.selectPageId || editor.data.pages[0].id;
    editor.lastUpdateAppData = JSON.stringify(editor.data);
    setLoading(false);
  }, []);

  useEffect(() => {
    initAppData();

    const onMouseWheel = e => {
      if (e.ctrlKey) {
        e.preventDefault();
      }
    };
    document.addEventListener('mousewheel', onMouseWheel, { passive: false });

    return () => {
      document.removeEventListener('mousewheel', onMouseWheel);
    };
  }, []);

  if (loading) {
    return <div>loading...</div>;
  }

  return (
    <div
      id="h5dsVideoEditor"
      key={editor.languageUpdateKey + '_' + editor.themeUpdateKey}
      ref={ref}
      className={styles.editor}
    >
      <div className={styles.sidebar} style={{ width: SIDEBAR_WIDTH }}>
        <Sidebar />
      </div>
      <div
        className={styles.sources}
        style={{
          left: SIDEBAR_WIDTH,
          width: layout.sourcesWidth,
          transform: show.sources ? 'translateX(0px)' : `translateX(${-layout.sourcesWidth}px)`,
        }}
      >
        <a onMouseDown={sourcesBarDrag} className={styles.sourcesBar}></a>
        <a
          onClick={() => {
            showPanel('sources', !show.sources);
          }}
          className={styles.flodButton}
        >
          <Left
            style={{ transform: `rotate(${show.sources ? 0 : 180}deg)` }}
            theme="outline"
            size="24"
            fill="var(--theme-text)"
          />
        </a>
        <Sources />
      </div>
      <div
        className={styles.header}
        style={{
          height: HEADER_HEIGHT,
          width: width - SIDEBAR_WIDTH - layout.sourcesWidth + (show.sources ? 0 : layout.sourcesWidth),
          left: show.sources ? layout.sourcesWidth + SIDEBAR_WIDTH : SIDEBAR_WIDTH,
        }}
      >
        <Header />
      </div>
      <div
        className={styles.center}
        style={{
          width:
            width -
            SIDEBAR_WIDTH -
            layout.optionsWidth -
            layout.sourcesWidth +
            (show.sources ? 0 : layout.sourcesWidth) +
            (show.options ? 0 : layout.optionsWidth),
          left: show.sources ? layout.sourcesWidth + SIDEBAR_WIDTH : SIDEBAR_WIDTH,
          top: HEADER_HEIGHT,
          transition: noAnimate ? 'none' : '0.5s',
        }}
      >
        <div className={styles.canvas} style={{ height: `calc(100% - ${HEADER_HEIGHT}px)` }}>
          <Canvas />
        </div>
      </div>
      <div
        className={styles.options}
        style={{
          width: layout.optionsWidth,
          top: HEADER_HEIGHT,
          transform: show.options ? 'translateX(0px)' : `translateX(${layout.optionsWidth}px)`,
        }}
      >
        <a onMouseDown={optionsBarDrag} className={styles.optionsBar}></a>
        <a
          onClick={() => {
            showPanel('options', !show.options);
          }}
          className={styles.flodButton}
        >
          <Right
            style={{ transform: `rotate(${show.options ? 0 : 180}deg)` }}
            theme="outline"
            size="24"
            fill="var(--theme-text)"
          />
        </a>
        {editor.movieCreateSuccess && <Options />}
      </div>
      <ColorBg style={{ bottom: 400, left: 300 }} />
      <ColorBg style={{ top: 100, right: 400 }} />
      <DragItem />
      <HotKeys />
    </div>
  );
}

export default observer(Editor);

import { Toast, Notification } from '@douyinfe/semi-ui';
import { editor } from '@stores/editor';
import { util } from '@utils/index';
import { pubsub } from '@utils/pubsub';
import { observer } from 'mobx-react';
import React, { useEffect, useRef } from 'react';
import { useHotkeys } from 'react-hotkeys-hook';
import type { HotkeysEvent } from 'react-hotkeys-hook/src/types';
import { server } from '@pages/editor/components/sources/my/server';
import { addImageItem } from './components/sources/addItem';
import { user } from '@stores/user';

export interface IProps {}

function HotKeys(props: IProps) {
  const mouseXY = useRef({ x: 0, y: 0 });
  useEffect(() => {
    const onMove = e => {
      // console.log(e.pageX, e.pageY);
      mouseXY.current.x = e.pageX;
      mouseXY.current.y = e.pageY;
    };
    document.addEventListener('mousemove', onMove);

    const pasteFuntion = async event => {
      event.stopPropagation();
      if (editor.copyTempData) {
        console.log('붙여넣기 요소');
        // if (!editor.copyTempData) {
        //   Toast.error('먼저 Ctrl + C를 사용하여 복사하십시오');
        //   return;
        // }
        const elems = editor.cloneElements(editor.copyTempData);
        editor.pageData.layers.unshift(...elems);
        editor.updateCanvas();
        editor.setSelectedElementIds(elems.map(d => d.id));
        editor.store.emitControl(elems.map(d => d.id));
      } else {
        // 로그인하지 않은 경우 먼저 로그인해야 합니다
        if (!user.info) {
          // pubsub.publish('showLoginModal');
          Toast.error('먼저 로그인하십시오');
          return;
        }

        const clipdata = event.clipboardData || (window as any).clipboardData;
        // console.log('clipdata', clipdata, item.getAsFile());
        const item = clipdata.items[0];
        const svgString = clipdata.getData('text/plain');
        let svgFile = null;
        if (svgString && util.isSVGString(svgString)) {
          const svgBlob = new Blob([svgString], { type: 'image/svg+xml' });
          svgFile = new File([svgBlob], 'image.svg', { type: 'image/svg+xml' });
        }

        // 只取剪切板中最新的
        if ((item && item.kind == 'file' && item.type.match(/^image\//i)) || svgFile) {
          const tid = Toast.info('파일 업로드 중...');
          // 파일 업로드
          const [res, err] = await server.formUpdate({
            files: svgFile ? [svgFile] : [item.getAsFile()],
            filename: `${util.createID()}.${svgFile ? 'svg' : 'png'}`,
            file_type: 'image', // file-普通文件 image-图片文件 audio-音频文件 video-视频文件
            app_id: editor.appid,
          });
          Toast.close(tid);

          // // 保存到素材库
          // const [item, err] = await server.createUserMaterial({
          //   app_id: editor.appid,
          //   name: name,
          //   urls: { url, thumb },
          //   attrs,
          // });

          const _img = await util.imgLazy(res.url);
          const imgLayer = await addImageItem({
            urls: { url: res.storage_path },
            attrs: {
              naturalWidth: _img.naturalWidth,
              naturalHeight: _img.naturalHeight,
            },
          });
          editor.setSelectedElementIds([imgLayer.id]);
          editor.store.emitControl([imgLayer.id]);

          Notification.open({
            title: '파일 업로드 성공!',
            content: 'SVG, JPEG, PNG, GIF 이미지 형식을 지원합니다',
            duration: 3,
            position: 'bottomRight',
          });
          return;
        }
      }
    };

    window.addEventListener('paste', pasteFuntion);

    return () => {
      window.removeEventListener('paste', pasteFuntion);
      document.removeEventListener('mousemove', onMove);
    };
  }, []);

  useHotkeys(
    [
      'ctrl+c', // 복사
      'ctrl+v', // 붙여넣기
      'ctrl+s', // 프로젝트 저장
      'ctrl+x', // 선택한 요소 잘라내기
      'ctrl+-', // 캔버스 축소
      'ctrl+=', // 캔버스 확대
      'ctrl+0', // 화면 크기에 맞게 캔버스 조정
      'ctrl+a', // 모두 선택
      'ctrl+d', // 선택 취소
      'ctrl+z', // 실행 취소
      'ctrl+shift+z', // 다시 실행
      'ctrl+]', // 선택한 레이어를 한 단계 위로 이동
      'ctrl+shift+}', // 선택한 레이어를 맨 위로 이동
      'ctrl+[', // 선택한 레이어를 한 단계 아래로 이동
      'ctrl+shift+{', // 선택한 레이어를 맨 아래로 이동
      'shift+up', // 위로 10px 이동
      'shift+down', // 아래로 10px 이동
      'shift+left', // 왼쪽으로 10px 이동
      'shift+right', // 오른쪽으로 10px 이동
      'up', // 위로 1px 이동
      'down', // 아래로 1px 이동
      'left', // 왼쪽으로 1px 이동
      'right', // 오른쪽으로 1px 이동
      'delete', // 선택한 요소 삭제
      'backspace', // 선택한 요소 삭제
    ],
    (event: KeyboardEvent, handler: HotkeysEvent) => {
      console.log('단축키 처리--->', event, handler, handler.keys);

      if (handler.ctrl && handler.keys.join('') !== 'v') {
        event.preventDefault();
      }

      if (handler.ctrl && handler.shift) {
        // ctrl + shift + *
        switch (handler.keys.join('')) {
          case 'z':
            console.log('다시 실행');
            pubsub.publish('keyboardRedo');
            break;
          case '}':
            console.log('선택한 레이어를 맨 위로 이동');
            editor.moveTopElement();
            break;
          case '{':
            console.log('선택한 레이어를 맨 아래로 이동');
            editor.moveBottomElement();
            break;
        }
      } else if (handler.ctrl) {
        // ctrl + *
        switch (handler.keys.join('')) {
          case ']':
            console.log('한 단계 위로 이동');
            editor.upOneElement();
            break;
          case '[':
            console.log('한 단계 아래로 이동');
            editor.downOneElement();
            break;
          case 'z':
            console.log('실행 취소');
            pubsub.publish('keyboardUndo');
            break;
          case 'a':
            console.log('모두 선택');
            editor.setContorlAndSelectedElemenent(editor.pageData.layers.map(layer => layer.id));
            break;
          case 'd':
            console.log('선택 취소');
            editor.setContorlAndSelectedElemenent([]);
            break;
          case '0':
            console.log('화면 크기에 맞게 캔버스 조정');
            pubsub.publish('keyboardSetViewSize', 'fit');
            break;
          case '-':
            console.log('캔버스 축소');
            pubsub.publish('keyboardSetViewSize', 'zoomIn');
            break;
          case '=':
            console.log('캔버스 확대');
            pubsub.publish('keyboardSetViewSize', 'zoomOut');
            break;
          case 'c':
            console.log('요소 복사');
            editor.copyElement();
            break;
          case 'x':
            console.log('요소 잘라내기');
            editor.cutElement();
            break;
          case 'v':
            // 上面
            break;
          case 's':
            console.log('프로젝트 수동 저장');
            pubsub.publish('keyboardSaveApp');
            break;
        }
      } else if (handler.shift) {
        // shfit + *
        switch (handler.keys.join('')) {
          case 'up':
            {
              console.log('위로 10px 이동');
              const elems = editor.getElementDataByIds([...editor.selectedElementIds]);
              elems.forEach(el => {
                el.y -= 10;
              });
              editor.updateCanvas();
            }
            break;
          case 'down':
            {
              console.log('아래로 10px 이동');
              const elems = editor.getElementDataByIds([...editor.selectedElementIds]);
              elems.forEach(el => {
                el.y += 10;
              });
              editor.updateCanvas();
            }
            break;
          case 'left':
            {
              console.log('왼쪽으로 10px 이동');
              const elems = editor.getElementDataByIds([...editor.selectedElementIds]);
              elems.forEach(el => {
                el.x -= 10;
              });
              editor.updateCanvas();
            }
            break;
          case 'right':
            {
              console.log('오른쪽으로 10px ���동');
              const elems = editor.getElementDataByIds([...editor.selectedElementIds]);
              elems.forEach(el => {
                el.x += 10;
              });
              editor.updateCanvas();
            }
            break;
        }
      } else {
        // 普通
        switch (handler.keys.join('')) {
          case 'up':
            {
              console.log('위로 1px 이동');
              const elems = editor.getElementDataByIds([...editor.selectedElementIds]);
              elems.forEach(el => {
                el.y -= 1;
              });
              editor.updateCanvas();
            }
            break;
          case 'down':
            {
              console.log('아래로 1px 이동');
              const elems = editor.getElementDataByIds([...editor.selectedElementIds]);
              elems.forEach(el => {
                el.y += 1;
              });
              editor.updateCanvas();
            }
            break;
          case 'left':
            {
              console.log('왼쪽으로 1px 이동');
              const elems = editor.getElementDataByIds([...editor.selectedElementIds]);
              elems.forEach(el => {
                el.x -= 1;
              });
              editor.updateCanvas();
            }
            break;
          case 'right':
            {
              console.log('오른쪽으로 1px 이동');
              const elems = editor.getElementDataByIds([...editor.selectedElementIds]);
              elems.forEach(el => {
                el.x += 1;
              });
              editor.updateCanvas();
            }
            break;
          case 'delete':
          case 'backspace':
            {
              console.log('삭제', [...editor.selectedElementIds]);
              editor.store.deleteLayers([...editor.selectedElementIds]);
              editor.updateCanvas();
              editor.store.emitControl([]);
              editor.record();
            }
            break;
        }
      }
    },
  );
  return null;
}

export default observer(HotKeys);

