                  forceUpdate();
                }}
                onBlur={() => {
                  editor.record({
                    type: 'update',
                    desc: '원형 수정',
                  });
                }}
              />
            </div>
            <div className={styles.inputs}>
              <InputNumber
                innerButtons
                value={util.toNum(d)}
