            editor.store.triggerRotation(elementData, elementData.rotation);
            forceUpdate();
          }}
          onAfterChange={() => {
            editor.record({
              type: 'update',
              desc: '회전 각도 수정',
            });
          }}
        />
      </div>
    </Item>
  );
}

