            prefix={
              <span className={styles.prefixIco}>
                <AutoLineWidth theme="filled" size="16" fill="var(--theme-icon)" />
              </span>
            }
            innerButtons
            onBlur={() => {
              editor.record({
                type: 'update',
                desc: '텍스트 간격 변경',
              });
            }}
          />
        </div>
      </div>
      <Item title="텍스트 색상">
        <SetColor
          gradual={true}
          list={true}
          color={elementData.textStyle.fill as IPaint}
          onChange={v => {
            console.log('vvv', v);
            elementData.textStyle.fill = v;
            elementData.textStyle = { ...elementData.textStyle };
            editor.updateCanvas();
          }}
        />
