export default class CoreView {
  private _props: IViewProps = {
    data: undefined,
    target: document.body,
    env: 'editor',
    resourceHost: '',
  };

  constructor(params: IViewProps) {
    Object.assign(this._props, params);
  }

  public init() {
    return new Promise(resolve => {
      const { target, callback, data, ...other } = this._props;
      if (!data) {
        return new Error('data 데이터는 페이지 데이터이며, 반드시 전달해야 합니다');
      }
      ReactDOM.createRoot(target!).render(
        <View
          {...other}
          data={data}
          target={target}
          callback={store => {
            if (callback) {
              callback(store);
            }
            resolve(store);
          }}
        />,
      );
    });
  }
}

import React, { useEffect, useMemo } from 'react';
import { Frame, Leafer } from 'leafer-ui';
