import UndoRedoManager from 'undo-redo-manager2';
import debounce from 'lodash/debounce';
import { useEffect, useRef } from 'react';
import Store from './stores/Store';
import * as utils from './tools/utils';
import type { RecordItem, RecordType } from './types/helper';
import { pubsub } from '@utils/pubsub';

export interface IProps {
  store: Store;
}

/**
 * 작업 기록, 되돌리기, 다시 실행
 * @param props
 * @returns
 */
function RecordManager(props: IProps) {
  const manager = useRef<any>();
  const store = props.store;

  useEffect(() => {
    manager.current = new UndoRedoManager({
      limit: 50, // 최대 기록 30회 설정, 기본값은 50회
    });

    const add = (item: RecordItem<RecordType>) => {
      // console.log('Record 데이터--------------->', item, utils.toJS(store.data));
      manager.current.add({
        id: utils.createID(),
        type: 'global',
        desc: item.desc,
        selecteds: [...item.selecteds],
        mdata: utils.cloneData(store.data),
      });
      // test 업데이트
      if (store.addRecordCallback) {
        store.addRecordCallback();
      }
    };

    // 데이터 복원
    const restore = (item: RecordItem<RecordType>, type: 'undo' | 'redo'): boolean => {
      if (!item) {
        console.warn('이미 초기 위치로 복원되었습니다');
        return false;
      }
      // 해당 데이���를 찾아서 매개변수 설정
      if (item.mdata) {
        utils.objectCopyValue(item.mdata, store.data);
      }
      // 뷰 업데이트
      store.update();
      store.editor.update();
      pubsub.publish('emitSelectElements', [...(item.selecteds || [])]);
      return true;
    };

    // 다시 실행
    const redo = () => {
      const item = manager.current.redo() as RecordItem<RecordType>;
      return restore(item, 'redo');
    };

    // 되돌리기
    const undo = () => {
      const item = manager.current.undo() as RecordItem<RecordType>;
      return restore(item, 'undo');
    };

    store.record = { add, redo, undo, debounceAdd: debounce(add, 500), manager: manager.current };

    add({ type: 'global', desc: '초기화 데이터', selecteds: [] });

    return () => {
      manager.current.destroy();
    };
  }, []);

  return null;
}

export default RecordManager;

import React, { useEffect, useState, useRef, useMemo, useReducer } from 'react';
import { BaseLayer, BasePage, ENV, ExLayer } from './types/data';
import { App, Box, Leafer, Rect, DragEvent, PointerEvent } from 'leafer-ui';
import FrameComp from './Frame';
import debounce from 'lodash/debounce';
import { addListener, removeListener } from 'resize-detector';
import Store from './stores/Store';
import RecordManager from './Record';
import ImageLayer from './layers/Image';
import TextLayer from './layers/Text';
import GroupLayer from './layers/Group';
import { Ruler } from 'leafer-x-ruler';
import { EditorEvent, EditorMoveEvent, EditorScaleEvent, EditorRotateEvent } from '@leafer-in/editor';
// import { ILeafer } from '@leafer-ui/interface';
import { ScrollBar } from '@leafer-in/scroll';
import { utils } from './tools';
import EditorLine from './leafer-extends/EditorLine';
import rotateIco from './rotate.png';

// console.log('exLayers', exLayers);

export interface IViewProps {
  data: BasePage;
  target: HTMLElement; // canvas가 들어갈 DOM 컨테이너
  env: ENV;
  resourceHost: string; // 리소스 파일 접두사
  exLayers?: ExLayer[]; // 확장 컴포넌트
  // 렌더링 후 실행
  callback?: (store: Store) => void;
  // 편집기 이벤트
  onControlSelect?: (e: EditorEvent, ids: string[]) => void;
  onControlScale?: (e: EditorEvent) => void;
  onControlMove?: (e: EditorEvent) => void;
  onControlRotate?: (e: EditorEvent) => void;
  onDragUp?: (e: EditorEvent) => void;
  onContextMenu?: (e: EditorEvent, layers: BaseLayer[]) => void;
  addRecordCallback?: () => void; // 기록 추가 콜백
}

export default function View(props: IViewProps) {
  const { target, data, env, resourceHost, exLayers = [] } = props;
  const [loaded, setLoaded] = useState<boolean>(false);
  const [, forceUpdate] = useReducer(x => x + 1, 0);
  const store = useMemo<Store>(() => {
    const s = new Store();
    s.resourceHost = resourceHost;
    s.data = data;
    s.env = env;
    s.updateView = forceUpdate;
    s.addRecordCallback = props.addRecordCallback;
    return s;
  }, []);

  // const [pos, setPos] = useState({
  //   x: (target.clientWidth - data.width * scale) / 2,
  //   y: (target.clientHeight - data.height * scale) / 2,
  // });

  useEffect(() => {
    const app = new App({
      view: target,
      editor: {
        lockRatio: 'corner',
        stroke: '#3f99f7',
        skewable: false,
        hover: false,
        middlePoint: { cornerRadius: 100, width: 20, height: 6 },
        rotatePoint: {
          width: 20,
          height: 20,
          fill: {
            type: 'image',
            url: rotateIco,
          },
        },
      },
      tree: {
        usePartRender: true,
      },
      sky: {
        type: 'draw',
        usePartRender: true,
      },
    });
    // console.log('app', app);
    //@ts-ignore
    store.app = app.tree;
    store.editor = app.editor;
    setLoaded(true);

    if (props.env === 'editor') {
      app.editor.on(EditorRotateEvent.ROTATE, (e: EditorEvent) => {
        // console.log('rotate', e);
        const list = (e as any).current.leafList.list;
        const layers = store.getLayerByIds(list.map(d => d.id));
        // 데이터 동기화
        list.forEach(box => {
          const layer = layers.find(d => d.id === box.id) as BaseLayer;
          if (layer) {
            layer.rotation = box.rotation;
            layer.x = utils.toNum(box.x);
            layer.y = utils.toNum(box.y);
          }
        });
        // forceUpdate();
        if (props.onControlRotate) {
          props.onControlRotate(e);
        }
      });

      app.editor.on(EditorScaleEvent.SCALE, (e: EditorEvent) => {
        // console.log('scale', e);
        const list = (e as any).current.leafList.list;
        const layers = store.getLayerByIds(list.map(d => d.id));

        // 그룹인 경우, children의 매개변수도 계산해야 합니다.
        const setGroupChildrenSize = box => {
          const ids = box.children.map(d => d.id);
          const innerLayers = store.getLayerByIds(ids);
          box.children.forEach(b => {
            const inlayer = innerLayers.find(d => d.id === b.id) as any;
            inlayer.width = b.width;
            inlayer.height = b.height;
            // 텍스트인 경우, x, y도 수정해야 합니다.
            if (inlayer.type === 'text') {
              inlayer.x = b.x;
              inlayer.y = b.y;
            }
            if (inlayer.type === 'group') {
              setGroupChildrenSize(b);
            }
          });
        };

        // 데이터 동기화
        list.forEach(box => {
          const layer = layers.find(d => d.id === box.id) as any;
          if (layer.type === 'text') {
            layer.x = box.x;
            layer.y = box.y;
          } else {
            layer.width = box.width;
            layer.height = box.height;
          }
          const func = store.controlScaleFuns[layer.id];
          if (func) {
            func();
          }
          // 그룹의 자식 요소의 크기 설정
          if (layer.type === 'group') {
            setGroupChildrenSize(box);
          }
        });
        // forceUpdate();
        if (props.onControlScale) {
          props.onControlScale(e);
        }
      });

      app.editor.on(EditorMoveEvent.MOVE, (e: EditorEvent) => {
        // console.log('move', e);
        const list = (e as any).current.leafList.list;
        const layers = store.getLayerByIds(list.map(d => d.id));
        // 데이터 동기화
        list.forEach(box => {
          const layer = layers.find(d => d.id === box.id);
          if (layer) {
            layer.x = box.x;
            layer.y = box.y;
          }
        });
        if (props.onControlMove) {
          props.onControlMove(e);
        }
      });

      app.editor.on(PointerEvent.MENU, e => {
        const list = (e as any).current.leafList.list;
        const layers = store.getLayerByIds(list.map(d => d.id));
        if (props.onContextMenu) {
          props.onContextMenu(e, layers);
        }
      });

      // 편집기 이벤트
      app.editor.on(EditorMoveEvent.SELECT, (e: EditorEvent) => {
        const ids: string[] = [];
        if (e.value) {
          if (e.value instanceof Array) {
            e.value.forEach(v => {
              ids.push(v.id);
            });
          } else {
            ids.push(e.value.id);
          }
        }
        const layers = store.getLayerByIds(ids);
        if (layers.length > 1) {
          app.editor.config.lockRatio = true;
        } else {
          if (layers[0]?.type === 'text' || layers[0]?.type === 'group') {
            app.editor.config.lockRatio = true;
          } else {
            app.editor.config.lockRatio = 'corner';
          }
        }

        ids.forEach(id => {
          const func = store.controlSelectFuns[id];
          if (func) {
            func();
          }
        });

        if (props.onControlSelect) {
          props.onControlSelect(e, ids);
        }
      });

      // 마우스 버튼을 놓음
      app.editor.on(DragEvent.UP, e => {
        const elementIds = utils.getIdsFromUI(store.editor.target);
        console.log('마우스 버튼을 놓음', elementIds);
        if (elementIds.length) {
          elementIds.forEach(id => {
            const fun = store.elementDragUp[id];
            if (fun) fun();
          });
        }
        store.record?.add({
          type: 'update',
          desc: '컨트롤러 마우스 버튼을 놓음',
          selecteds: [...elementIds],
        });
        if (props.onDragUp) {
          props.onDragUp(e);
        }
      });

      new ScrollBar(app as any);
      // new EditorLine(app);

      // 눈금자
      const ruler = new Ruler(app as any);
      // 사용자 정의 테마 추가
      ruler.addTheme('dark2', {
        backgroundColor: '#16161a',
        textColor: 'rgba(255, 255, 255, 0.5)',
        borderColor: '#686868',
        highlightColor: 'rgba(0, 102, 255, 0.5)',
      });
      store.ruler = ruler;
    }

    // 컨테이너 변경 사항 모니터링
    const onResize = debounce(() => {
      store.autoViewSize();
    }, 100);
    addListener(target, onResize);

    setTimeout(() => {
      store.autoViewSize();
    }, 100);

    if (props.callback) {
      props.callback(store);
    }
    return () => {
      removeListener(target, onResize);
      // app.destroy();
    };
  }, [target, store]);

  useEffect(() => {
    if (store) {
      store.data = data;
    }
  }, [data]);
  if (!loaded) {
    return;
  }

  return (
    <>
      <FrameComp data={{ ...data }} parent={store.app as any}>
        {data.layers.map((layer, i) => {
          switch (layer.type) {
            case 'image':
              return (
                <ImageLayer
                  key={layer.id}
                  hide={layer._hide}
                  lock={layer._lock}
                  dirty={layer._dirty}
                  zIndex={99999 - i}
                  layer={layer}
                  store={store}
                  env={env}
                />
              );
            case 'text':
              return (
                <TextLayer
                  key={layer.id}
                  hide={layer._hide}
                  lock={layer._lock}
                  dirty={layer._dirty}
                  zIndex={99999 - i}
                  layer={layer}
                  store={store}
                  env={env}
                />
              );
            case 'group':
              return (
                <GroupLayer
                  key={layer.id}
                  hide={layer._hide}
                  lock={layer._lock}
                  dirty={layer._dirty}
                  zIndex={99999 - i}
                  layer={layer}
                  store={store}
                  env={env}
                />
              );
            default: {
              const exLayer = exLayers.find(d => d.config.pid === layer.type);
              if (exLayer) {
                const ELayer = exLayer.Layer as any;
                return (
                  <ELayer
                    key={layer.id}
                    hide={layer._hide}
                    lock={layer._lock}
                    dirty={layer._dirty}
                    zIndex={99999 - i}
                    layer={layer}
                    store={store}
                    env={env}
                  />
                );
              }
            }
          }
          return null;
        })}
      </FrameComp>
      {env === 'editor' && <RecordManager store={store} />}
    </>
  );
}

import { useEffect } from 'react';
import { IShadowEffect, IBox, IUI, IText } from '@leafer-ui/interface';
import { BaseLayer } from '../types/data';
import Store from '../stores/Store';

export default function useLayerBaseStyle(layer: BaseLayer, box: IUI, store: Store, zIndex: number) {
  useEffect(() => {
    // x, y, width, height
    box.x = layer.x;
    box.y = layer.y;
    box.opacity = layer.opacity;

    // 흐림
    box.blur = layer.blur;

    // 혼합 모드
    box.blendMode = layer.blendMode;

    // 테두리
    if (layer.type === 'image') {
      const imgUI = box.children[0];
      imgUI.stroke = layer.border.stroke;
      imgUI.strokeWidth = layer.border.visible ? layer.border.strokeWidth : 0;
      imgUI.dashPattern = layer.border.dashPattern;
    } else {
      box.stroke = layer.border.stroke;
      box.strokeWidth = layer.border.visible ? layer.border.strokeWidth : 0;
      box.dashPattern = layer.border.dashPattern;
    }

    // 회전
    box.rotation = layer.rotation;
    // box.rotateOf({ x: box.width / 2, y: box.height / 2 }, layer.rotation - box.rotation);
  }, [layer.x, layer.y, layer.opacity, layer.blendMode, layer.blur, layer.border, layer.rotation]);

  useEffect(() => {
    box.zIndex = zIndex;
  }, [zIndex]);

  // 그림자
  useEffect(() => {
    if (layer.shadow && layer.shadow.visible) {
      if (['image', 'text'].includes(layer.type)) {
        const imgUI = box.children[0];
        imgUI.shadow = { ...layer.shadow };
      } else {
        (box.shadow as IShadowEffect) = { ...layer.shadow };
      }
    } else {
      if (['image', 'text'].includes(layer.type)) {
        const imgUI = box.children[0];
        imgUI.shadow = undefined;
      } else {
        box.shadow = undefined;
      }
    }
  }, [
    layer.shadow?.x,
    layer.shadow?.y,
    layer.shadow?.blur,
    layer.shadow?.color,
    layer.shadow?.visible,
    layer.shadow?.spread,
  ]);

  useEffect(() => {
    box.visible = !layer._hide;
    box.locked = layer._lock;
    if (layer._lock) {
      box.hittable = false;
    } else {
      box.hittable = true;
    }
  }, [layer._hide, layer._lock]);

  return [];
}

import React, { useEffect, useMemo } from 'react';
import { Group } from 'leafer-ui';
import { LayerProps } from '../types/helper';
import { GroupLayer } from '../types/data';
import useLayerBaseStyle from '../hooks/useLayerBaseStyle';

import ImageLayer from './Image';
import TextLayer from './Text';
import exLayers from '@plugins/index';

export default function GroupComp(props: LayerProps) {
  const layer = props.layer as GroupLayer;
  const groupBox = useMemo(() => {
    const group = new Group({
      editable: props.isChild ? false : true,
      hitChildren: false,
      x: layer.x,
      y: layer.y,
      rotation: layer.rotation,
      opacity: layer.opacity,
      fill: 'rgba(0,0,0,0.0)',
    });
    group.id = layer.id;
    group.zIndex = props.zIndex;
    props.parent!.add(group as any);
    return group;
  }, []);

  // 공통 use
  useLayerBaseStyle(layer, groupBox as any, props.store, props.zIndex);

  // useEffect(() => {
  //   // 너비와 높이 설정
  //   groupBox.width = layer.width;
  //   groupBox.height = layer.height;
  // }, [layer.width, layer.height]);

  useEffect(() => {
    // 자식 컴포넌트의 업데이트 메서드 호출
    props.store.controlSelectFuns[layer.id] = () => {
      layer.childs.forEach(d => {
        if (props.store.controlSelectFuns[d.id]) {
          props.store.controlSelectFuns[d.id]();
        }
      });
    };

    // 자식 컴포넌트의 업데이트 메서드 호출
    props.store.controlScaleFuns[layer.id] = () => {
      layer.childs.forEach(d => {
        if (props.store.controlScaleFuns[d.id]) {
          props.store.controlScaleFuns[d.id]();
        }
      });
    };

    return () => {
      delete props.store.controlScaleFuns[layer.id];
      groupBox.remove();
      groupBox.destroy();
    };
  }, []);

  const { store, env } = props;

  console.log('更新组---》');

  return (
    <>
      {[...layer.childs].map((layer, i) => {
        switch (layer.type) {
          case 'image':
            return (
              <ImageLayer
                key={layer.id}
                hide={layer._hide}
                lock={layer._lock}
                dirty={layer._dirty}
                parent={groupBox}
                isChild={true}
                zIndex={99999 - i}
                layer={layer}
                store={store}
                env={env}
              />
            );
          case 'text':
            return (
              <TextLayer
                key={layer.id}
                hide={layer._hide}
                lock={layer._lock}
                dirty={layer._dirty}
                isChild={true}
                parent={groupBox}
                zIndex={99999 - i}
                layer={layer}
                store={store}
                env={env}
              />
            );
          case 'group':
            return (
              <GroupComp
                key={layer.id}
                hide={layer._hide}
                lock={layer._lock}
                dirty={layer._dirty}
                isChild={true}
                parent={groupBox}
                zIndex={99999 - i}
                layer={layer}
                store={store}
                env={env}
              />
            );
          default: {
            const exLayer = exLayers.find(d => d.config.pid === layer.type);
            if (exLayer) {
              const ELayer = exLayer.Layer as any;
              return (
                <ELayer
                  key={layer.id}
                  hide={layer._hide}
                  lock={layer._lock}
                  dirty={layer._dirty}
                  isChild={true}
                  parent={groupBox}
                  zIndex={99999 - i}
                  layer={layer}
                  store={store}
                  env={env}
                />
              );
            }
          }
        }
        return null;
      })}
    </>
  );
}

