import { storage } from '@utils/storage';
import { themeDark } from './theme-dark';
import { themeLight } from './theme-light';

export type ThemeType = 'light' | 'dark';

export enum ThemeName {
  DARK = 'dark',
  LIGHT = 'light',
}

class Theme {
  theme: ThemeType = 'dark';
  constructor() {
    this.theme = storage.local.get('theme') || 'dark';
    this.setTheme(this.theme);
    // storage.local.set('theme', this.theme);
  }
  /**
   * 테마 전환
   */
  setTheme = (themeName: ThemeType): void => {
    this.theme = themeName;
    storage.local.set('theme', themeName);
    document.body.setAttribute('theme-mode', themeName);
    switch (themeName) {
      case ThemeName.DARK:
        for (const key in themeDark) {
          document.body.style.setProperty(key, themeDark[key]);
        }
        break;
      case ThemeName.LIGHT:
        for (const key in themeLight) {
          document.body.style.setProperty(key, themeLight[key]);
        }
        break;
    }
  };

  getTheme = (): ThemeType => {
    return this.theme || storage.local.get('theme') || 'dark';
  };

  // 전달된 다크 모드 색상 값을 기반으로 다른 환경에서 해당 색상 값을 자동으로 전환
  findColor = (val: string): string => {
    if (this.theme === 'dark') {
      return val;
    }
    for (const key in themeDark) {
      if (themeDark[key] === val) {
        return themeLight[key];
      }
    }
    return '';
  };
}

export const theme = new Theme();

import { matchRoutes } from 'react-router-config';
import { routes } from '../routes.config';
import { config } from '@config/index';

export function checkAuth(): boolean {
  const mroutes = matchRoutes(
    routes,
    config.basename ? location.pathname.replace(`/${config.basename}`, '') : location.pathname,
  );
  let auth = false;
  const last = mroutes[mroutes.length - 1];
  if (last?.route.meta) {
    auth = last.route.meta.auth;
  }
  return auth;
}

// 브라우저가 Google Chrome인지 확인
export function isChrome() {
  return /Chrome/.test(navigator.userAgent) && /Google Inc/.test(navigator.vendor);
}

// Google Chrome의 버전 번호를 가져옴
export function getChromeVersion() {
  const match = navigator.userAgent.match(/Chrome\/(\d+)/);
  return match ? parseInt(match[1], 10) : 0;
}

// Google Chrome 버전이 98보다 큰지 확인
export function isChromeVersionGreaterThan(ver: number) {
  const chromeVersion = getChromeVersion();
  return chromeVersion && chromeVersion > ver;
}

