export function getRandomInt(min: number, max: number) {
  min = Math.ceil(min); // 确保min是整数
  max = Math.floor(max); // 确保max是整数
  return Math.floor(Math.random() * (max - min + 1)) + min; // 返回介于min和max之间的整数
}

// Base64 to Blob
export function dataURLtoBlob(dataurl: string): Blob {
  const arr: string[] = dataurl.split(','),
    //@ts-ignore
    mime = arr[0].match(/:(.*?);/)[1],
    bstr = atob(arr[1]);
  let n: number = bstr.length;
  const u8arr = new Uint8Array(n);
  while (n--) {
    u8arr[n] = bstr.charCodeAt(n);
  }
  return new Blob([u8arr], { type: mime });
}

export function scaleBase64(base64: string, scale: number): Promise<string> {
  return new Promise(resolve => {
    // 创建一个 Image 对象
    let img = new Image();
    img.src = base64;

    // 等待图片加载完成
    img.onload = function () {
      // 计算缩小后的宽度和高度
      let newWidth = img.width * 0.5;
      let newHeight = img.height * 0.5;

      // 创建一个 Canvas 元素
      let canvas = document.createElement('canvas');
      let ctx = canvas.getContext('2d');

      // 设置 Canvas 尺寸
      canvas.width = newWidth;
      canvas.height = newHeight;

      // 在 Canvas 上绘制缩小后的图片
      ctx.drawImage(img, 0, 0, newWidth, newHeight);

      // 将 Canvas 转换为 base64 图片
      const resizedBase64 = canvas.toDataURL('image/png');

      // 输出缩小后的 base64 图片
      resolve(resizedBase64);
    };
  });
}

/**
 * 异步加载媒体资源
 * @param src
 * @param type
 * @returns
 */
export function mediaLazy(
  src: string,
  time?: number,
  type?: 'video' | 'audio',
): Promise<HTMLVideoElement | HTMLAudioElement> {
  return new Promise((resolve, reject) => {
    const media = document.createElement(type || 'video');
    media.preload = 'auto';
    media.crossOrigin = 'Anonymous';
    media.autoplay = false;
    media.src = src;
    media.setAttribute('playsinline', '');
    media.setAttribute('webkit-playsinline', '');
    if (time !== undefined) {
      media.currentTime = time;
    }
    media.onerror = err => {
      console.error('media资源失败', src, err);
      reject();
    };
    media.oncanplaythrough = () => {
      console.log('加载成功');
      resolve(media);
    };
  });
}

