export const timeToSec = (time: string): number => {
  const timeArr = time.split(':');
  const hour = Number(timeArr[0]);
  const minute = Number(timeArr[1]);
  const sec = timeArr[2];
  return Number(3600 * hour) + Number(60 * minute) + Number(sec);
