/**
 * 将对象转换为querystring，如 {a: 1, b: 2} 转换为 a=1&b=2
 * @param {object} data Query对象
 * @returns 字符串querystring
 */
export const data2QueryString = (data: any[]): string => {
  const str: any[] = [];
  if (data) {
    for (const key in data) {
      str.push(`${key}=${data[key]}`);
    }
  }
  return str.join('&');
};

